:root {
  --ink: #0b0b10;
  --panel: rgba(10, 11, 16, 0.82);
  --panel-line: rgba(255, 255, 255, 0.13);
  --white: #f4f2e9;
  --muted: #9d9da6;
  --green: #a9ff3f;
  --green-deep: #58c21e;
  --pink: #ff3d8b;
  --yellow: #ffd83d;
  --red: #ff5349;
  --cyan: #55d9ff;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #07080c;
  color: var(--white);
  font-family: "Arial Narrow", "Roboto Condensed", "Helvetica Neue", Arial, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}

button {
  color: inherit;
  font: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #07080c;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: none;
}

.hidden { display: none !important; }

/* ------------------------------------------------------------------ */
/* HUD                                                                 */
/* ------------------------------------------------------------------ */

#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  font-stretch: condensed;
}

.hud-top-left {
  position: absolute;
  left: 26px;
  top: calc(22px + var(--safe-top));
  width: 270px;
  filter: drop-shadow(0 4px 18px rgba(0, 0, 0, 0.55));
}

.identity {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 9px;
}

.identity-mark {
  display: grid;
  place-items: center;
  width: 37px;
  height: 37px;
  border: 1px solid rgba(255, 255, 255, 0.34);
  border-radius: 50%;
  background: rgba(7, 8, 12, 0.74);
  color: var(--green);
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 22px;
  line-height: 1;
  transform: skew(-6deg);
}

.identity strong {
  display: block;
  font-size: 13px;
  letter-spacing: 0.18em;
  line-height: 1.1;
}

.identity span {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.bars {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
}

.bar {
  position: relative;
  height: 12px;
  background: rgba(5, 6, 10, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.15);
  transform: skewX(-13deg);
  overflow: hidden;
}

.bar i {
  display: block;
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #46b81d, var(--green));
  box-shadow: 0 0 12px rgba(169, 255, 63, 0.35);
  transition: width 160ms ease-out;
}

.bar.armor i {
  width: 0%;
  background: linear-gradient(90deg, #148bd1, var(--cyan));
  box-shadow: 0 0 12px rgba(85, 217, 255, 0.35);
}

.bar span {
  position: absolute;
  right: 4px;
  top: 0;
  font-size: 7px;
  line-height: 10px;
  letter-spacing: 0.16em;
  color: rgba(255, 255, 255, 0.66);
}

.cash-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-top: 8px;
  padding-left: 2px;
}

.cash-icon {
  color: var(--green);
  font-weight: 900;
  font-size: 15px;
}

.cash-row strong {
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 24px;
  letter-spacing: 0.04em;
  color: var(--green);
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.7);
}

.cash-label {
  color: var(--muted);
  font-size: 8px;
  letter-spacing: 0.22em;
}

.hud-top-right {
  position: absolute;
  right: 26px;
  top: calc(22px + var(--safe-top));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
  filter: drop-shadow(0 4px 14px rgba(0, 0, 0, 0.55));
}

.wanted {
  display: flex;
  gap: 3px;
  font-size: 25px;
  line-height: 1;
  letter-spacing: 0.04em;
  color: rgba(255, 255, 255, 0.13);
  text-shadow: 0 2px 2px rgba(0, 0, 0, 0.75);
}

.wanted span {
  transition: color 120ms, transform 120ms;
}

.wanted span.on {
  color: var(--white);
  text-shadow: 0 0 12px rgba(255, 255, 255, 0.55), 0 2px 0 rgba(0, 0, 0, 0.9);
  animation: wantedPulse 1.3s infinite alternate;
}

.wanted.flash span.on {
  color: var(--red);
  text-shadow: 0 0 15px rgba(255, 83, 73, 0.9), 0 2px 0 #000;
}

@keyframes wantedPulse {
  from { transform: scale(1); }
  to { transform: scale(1.07); }
}

.clock-row {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--muted);
}

#clock {
  color: var(--white);
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 18px;
  letter-spacing: 0.08em;
}

#district {
  padding-left: 10px;
  border-left: 1px solid rgba(255, 255, 255, 0.24);
}

.icon-btn {
  pointer-events: auto;
  position: absolute;
  right: 0;
  top: 62px;
  width: 27px;
  height: 27px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 50%;
  background: rgba(8, 9, 14, 0.64);
  color: var(--muted);
  font-size: 13px;
  line-height: 1;
}

.icon-btn.off { color: #555; text-decoration: line-through; }

.mission-panel {
  position: absolute;
  left: 26px;
  top: calc(153px + var(--safe-top));
  width: 296px;
  padding: 13px 16px 13px 18px;
  background: linear-gradient(90deg, rgba(7, 8, 12, 0.88), rgba(7, 8, 12, 0.54) 70%, transparent);
  border-left: 3px solid var(--yellow);
  filter: drop-shadow(0 4px 18px rgba(0, 0, 0, 0.4));
}

.mission-panel::after {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 1px;
  background: linear-gradient(90deg, rgba(255, 216, 61, 0.75), transparent);
}

.mission-kicker {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--yellow);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.24em;
}

.mission-kicker i {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, rgba(255, 216, 61, 0.4), transparent);
}

.mission-panel h2 {
  margin: 5px 0 4px;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 22px;
  font-weight: 400;
  letter-spacing: 0.04em;
  line-height: 1;
}

.mission-panel p {
  margin: 0;
  max-width: 260px;
  color: #d5d4cc;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.45;
  letter-spacing: 0.02em;
}

.mission-distance {
  margin-top: 5px;
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.14em;
}

.mission-distance:empty { display: none; }

.radar-wrap {
  position: absolute;
  left: 26px;
  bottom: calc(25px + var(--safe-bottom));
  width: 188px;
  height: 188px;
  border-radius: 50%;
  filter: drop-shadow(0 8px 24px rgba(0, 0, 0, 0.7));
}

#radar {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: #0c0e13;
}

.radar-ring {
  position: absolute;
  inset: -4px;
  border: 2px solid rgba(255, 255, 255, 0.24);
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px rgba(0, 0, 0, 0.65), 0 0 0 1px rgba(0, 0, 0, 0.5);
  pointer-events: none;
}

.radar-n {
  position: absolute;
  top: 7px;
  left: 50%;
  transform: translateX(-50%);
  color: rgba(255, 255, 255, 0.62);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-shadow: 0 1px 3px #000;
}

.weapon-hud {
  position: absolute;
  right: 27px;
  bottom: calc(34px + var(--safe-bottom));
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  background: rgba(8, 9, 13, 0.62);
  border-right: 2px solid rgba(255, 255, 255, 0.36);
  filter: drop-shadow(0 4px 12px rgba(0, 0, 0, 0.5));
}

.weapon-icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: var(--white);
  font-size: 18px;
  transform: skew(-8deg);
}

.weapon-hud strong {
  display: block;
  font-size: 10px;
  letter-spacing: 0.18em;
  line-height: 1.2;
}

.weapon-hud span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.weapon-hud b {
  color: var(--white);
  font-size: 14px;
}

.weapon-hud i { font-style: normal; }

.vehicle-hud {
  position: absolute;
  right: 28px;
  bottom: calc(97px + var(--safe-bottom));
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 12px;
  background: rgba(8, 9, 13, 0.7);
  border-bottom: 2px solid var(--pink);
  filter: drop-shadow(0 4px 16px rgba(0, 0, 0, 0.6));
}

.speed-dial {
  text-align: right;
  border-right: 1px solid rgba(255, 255, 255, 0.18);
  padding-right: 11px;
}

#speed-number {
  font-family: Impact, "Arial Black", sans-serif;
  font-size: 31px;
  line-height: 0.9;
  letter-spacing: 0.02em;
}

.speed-dial span {
  color: var(--muted);
  font-size: 7px;
  letter-spacing: 0.2em;
}

.vehicle-meta strong {
  display: block;
  font-size: 10px;
  letter-spacing: 0.17em;
}

.vehicle-meta span {
  display: block;
  color: var(--muted);
  font-size: 8px;
  letter-spacing: 0.12em;
}

.speed-track {
  width: 108px;
  height: 3px;
  margin: 5px 0;
  background: rgba(255, 255, 255, 0.13);
}

.speed-track i {
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, var(--green), var(--yellow), var(--pink));
}

.prompt {
  position: absolute;
  left: 50%;
  bottom: calc(90px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 13px 8px 9px;
  background: rgba(6, 7, 11, 0.86);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 3px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.15em;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5);
  animation: promptIn 160ms ease-out;
}

@keyframes promptIn {
  from { opacity: 0; transform: translate(-50%, 5px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 19px;
  height: 19px;
  padding: 0 4px;
  border: 1px solid rgba(255, 255, 255, 0.34);
  border-bottom-width: 2px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--white);
  font-family: inherit;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.02em;
}

.toast-stack {
  position: absolute;
  top: calc(20px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  width: min(560px, 80vw);
}

.toast {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 14px;
  background: rgba(8, 9, 14, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-bottom: 2px solid var(--green);
  color: var(--white);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  animation: toastIn 220ms ease-out, toastOut 300ms ease-in 2.6s forwards;
}

.toast.warn { border-bottom-color: var(--red); }
.toast.money { border-bottom-color: var(--green); color: var(--green); }
.toast.gold { border-bottom-color: var(--yellow); color: var(--yellow); }
.toast.blue { border-bottom-color: var(--cyan); color: var(--cyan); }

@keyframes toastIn {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes toastOut {
  to { opacity: 0; transform: translateY(-8px); }
}

.mission-banner {
  position: absolute;
  top: 33%;
  left: 0;
  width: 100%;
  padding: 20px 0 19px;
  text-align: center;
  background: linear-gradient(90deg, transparent, rgba(6, 7, 11, 0.86) 18%, rgba(6, 7, 11, 0.86) 82%, transparent);
  animation: bannerIn 500ms cubic-bezier(.2,.8,.2,1);
}

.mission-banner::before,
.mission-banner::after {
  content: "";
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: min(600px, 75vw);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 216, 61, 0.7), transparent);
}
.mission-banner::before { top: 0; }
.mission-banner::after { bottom: 0; }

.mission-banner span {
  display: block;
  color: var(--yellow);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.55em;
}

.mission-banner strong {
  display: block;
  margin: 2px 0 3px;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(38px, 5vw, 62px);
  font-weight: 400;
  letter-spacing: 0.03em;
  line-height: 0.98;
  text-shadow: 3px 3px 0 rgba(0, 0, 0, 0.8);
}

.mission-banner i {
  display: block;
  color: #c7c6bd;
  font-size: 10px;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

@keyframes bannerIn {
  from { opacity: 0; transform: scaleX(0.86); }
  to { opacity: 1; transform: scaleX(1); }
}

.objective-arrow {
  position: absolute;
  left: 50%;
  top: 92px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  color: var(--yellow);
  transform: translateX(-50%);
  filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.8));
}

.arrow-head {
  width: 0;
  height: 0;
  border-left: 7px solid transparent;
  border-right: 7px solid transparent;
  border-bottom: 11px solid var(--yellow);
  animation: arrowBob 0.8s infinite alternate ease-in-out;
}

.objective-arrow span {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

@keyframes arrowBob {
  to { transform: translateY(4px); }
}

.hint-bar {
  position: absolute;
  left: 50%;
  bottom: calc(17px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 7px 13px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(7, 8, 12, 0.55);
  color: rgba(255, 255, 255, 0.46);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.1em;
  white-space: nowrap;
}

.hint-bar span { display: flex; align-items: center; gap: 4px; }
.hint-bar kbd { height: 15px; min-width: 15px; font-size: 7px; border-color: rgba(255, 255, 255, 0.16); }

/* ------------------------------------------------------------------ */
/* Screens                                                             */
/* ------------------------------------------------------------------ */

.screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
}

.title-screen {
  align-items: stretch;
  justify-content: flex-start;
  flex-direction: column;
  background:
    radial-gradient(ellipse at 72% 40%, rgba(255, 61, 139, 0.08), transparent 42%),
    linear-gradient(180deg, rgba(4, 5, 9, 0.34) 0%, rgba(4, 5, 9, 0.08) 38%, rgba(4, 5, 9, 0.8) 82%, rgba(4, 5, 9, 0.97) 100%);
  padding: clamp(22px, 4vw, 55px) clamp(24px, 6vw, 90px);
  animation: titleFade 0.6s ease-out;
}

@keyframes titleFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

.title-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(4, 5, 9, 0.7) 0%, transparent 58%),
    repeating-linear-gradient(0deg, rgba(255,255,255,0.016) 0 1px, transparent 1px 3px);
  pointer-events: none;
}

.title-grain {
  position: absolute;
  inset: -50%;
  opacity: 0.1;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.6'/%3E%3C/svg%3E");
  animation: grain 0.24s steps(2) infinite;
}

@keyframes grain {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(-1%, -1%); }
}

.title-topline {
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  color: rgba(255, 255, 255, 0.5);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.32em;
  z-index: 2;
}

.live-dot { color: var(--green); }

.title-core {
  position: relative;
  z-index: 2;
  margin-top: auto;
  margin-bottom: auto;
  max-width: 790px;
  padding-top: 2vh;
}

.title-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 7px;
  color: var(--yellow);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.48em;
}

.title-eyebrow::before {
  content: "";
  width: 28px;
  height: 2px;
  background: var(--yellow);
}

.game-logo {
  position: relative;
  margin: 0;
  font-family: Impact, "Arial Black", "Helvetica Neue", sans-serif;
  font-weight: 400;
  line-height: 0.82;
  letter-spacing: 0.005em;
  transform: skewX(-3deg);
  filter: drop-shadow(6px 8px 0 rgba(0, 0, 0, 0.4));
}

.logo-small {
  display: block;
  margin-left: 5px;
  margin-bottom: 2px;
  color: rgba(255, 255, 255, 0.65);
  font-family: "Arial Black", Arial, sans-serif;
  font-size: clamp(9px, 1vw, 13px);
  font-weight: 900;
  letter-spacing: 0.55em;
  line-height: 1.1;
}

.logo-main {
  position: relative;
  display: block;
  color: #fff;
  font-size: clamp(65px, 10.5vw, 164px);
  text-shadow:
    4px 4px 0 var(--pink),
    8px 8px 0 rgba(0, 0, 0, 0.55);
  white-space: nowrap;
}

.logo-main::after {
  content: "LOS SANTOS";
  position: absolute;
  inset: 0;
  color: transparent;
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.18);
  transform: translate(2px, 1px);
}

.logo-two {
  position: absolute;
  right: -3px;
  bottom: -14px;
  display: grid;
  place-items: center;
  width: clamp(48px, 5.5vw, 82px);
  height: clamp(37px, 4.2vw, 62px);
  background: var(--green);
  color: #0b0d08;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(28px, 3.3vw, 50px);
  line-height: 1;
  transform: rotate(-7deg) skewX(0);
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.55);
}

.tagline {
  margin: clamp(18px, 3vh, 32px) 0 0 4px;
  color: rgba(255, 255, 255, 0.72);
  font-size: clamp(11px, 1.05vw, 14px);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.title-actions {
  display: flex;
  align-items: center;
  gap: 22px;
  margin-top: 27px;
}

.primary-btn {
  pointer-events: auto;
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 26px;
  min-width: 260px;
  padding: 15px 17px 15px 20px;
  background: var(--green);
  color: #0a0d07;
  border: 0;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.17em;
  box-shadow: 0 0 0 1px rgba(169, 255, 63, 0.25), 0 10px 35px rgba(0, 0, 0, 0.4);
  transition: background 130ms, transform 130ms, box-shadow 130ms;
}

.primary-btn i {
  font-style: normal;
  font-size: 20px;
  line-height: 0.5;
  transition: transform 130ms;
}

.primary-btn:hover {
  background: #c3ff72;
  transform: translateY(-2px);
  box-shadow: 0 0 24px rgba(169, 255, 63, 0.25), 0 13px 38px rgba(0, 0, 0, 0.5);
}

.primary-btn:hover i { transform: translateX(4px); }

.text-btn {
  pointer-events: auto;
  color: rgba(255, 255, 255, 0.56);
  padding: 8px 2px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.16em;
  transition: color 130ms, border-color 130ms;
}

.text-btn:hover { color: #fff; border-color: var(--green); }
.text-btn.danger:hover { color: var(--red); border-color: var(--red); }

.title-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 20px;
  margin-top: 28px;
  color: rgba(255, 255, 255, 0.36);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.title-controls b {
  color: rgba(255, 255, 255, 0.72);
  font-weight: 900;
}

.title-bottom {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  gap: 22px;
  width: 100%;
  color: rgba(255, 255, 255, 0.36);
}

.rating-box {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 9px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: rgba(255, 255, 255, 0.72);
}

.rating-box b {
  padding-right: 8px;
  border-right: 1px solid rgba(255, 255, 255, 0.24);
  font-size: 21px;
  line-height: 1;
}

.rating-box span {
  font-size: 6px;
  font-weight: 800;
  line-height: 1.35;
  letter-spacing: 0.1em;
}

.title-bottom p {
  max-width: 420px;
  margin: 0 0 2px;
  font-size: 8px;
  line-height: 1.5;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.build-tag {
  margin-left: auto;
  font-size: 7px;
  letter-spacing: 0.22em;
}

.pause-screen {
  background: rgba(4, 5, 9, 0.7);
  backdrop-filter: blur(9px);
  z-index: 40;
}

.pause-card {
  width: min(470px, calc(100vw - 38px));
  padding: 33px 38px 28px;
  background: linear-gradient(155deg, rgba(20, 21, 28, 0.98), rgba(8, 9, 13, 0.98));
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-top: 3px solid var(--green);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65);
}

.pause-kicker {
  color: var(--green);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.35em;
}

.pause-card h2 {
  margin: 7px 0 22px;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(40px, 6vw, 61px);
  font-weight: 400;
  line-height: 0.88;
  letter-spacing: 0.02em;
}

.pause-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin-bottom: 24px;
  background: rgba(255, 255, 255, 0.1);
}

.pause-stats div {
  padding: 11px 10px;
  background: #101117;
}

.pause-stats span {
  display: block;
  color: var(--muted);
  font-size: 7px;
  letter-spacing: 0.18em;
}

.pause-stats strong {
  display: block;
  margin-top: 4px;
  font-size: 13px;
  letter-spacing: 0.07em;
}

.pause-card .primary-btn { width: 100%; margin-bottom: 9px; }
.pause-card > .text-btn { display: block; margin: 7px auto 0; }

.pause-help {
  display: flex;
  flex-wrap: wrap;
  gap: 7px 13px;
  margin-top: 21px;
  padding-top: 13px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--muted);
  font-size: 7px;
  letter-spacing: 0.1em;
}

.pause-help span { display: flex; align-items: center; gap: 4px; }

.fail-screen {
  background: radial-gradient(ellipse at center, rgba(63, 9, 12, 0.55), rgba(5, 4, 6, 0.94) 68%);
  z-index: 42;
  animation: failIn 0.45s ease-out;
}

@keyframes failIn { from { opacity: 0; } }

.fail-card {
  width: min(650px, calc(100vw - 36px));
  text-align: center;
  padding: 20px;
}

.fail-kicker {
  color: var(--red);
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(62px, 12vw, 130px);
  line-height: 0.85;
  letter-spacing: 0.05em;
  text-shadow: 5px 5px 0 rgba(0, 0, 0, 0.65);
  transform: skewX(-4deg);
}

.fail-card h2 {
  margin: 14px 0 8px;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(28px, 4vw, 43px);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: 0.04em;
}

.fail-card p {
  margin: 0 auto 27px;
  max-width: 410px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
  letter-spacing: 0.04em;
}

.fail-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.end-screen {
  background: radial-gradient(ellipse at 50% 15%, rgba(81, 108, 20, 0.18), transparent 48%), rgba(4, 5, 9, 0.83);
  backdrop-filter: blur(6px);
  z-index: 42;
}

.end-card {
  width: min(650px, calc(100vw - 36px));
  padding: 38px 45px;
  background: linear-gradient(160deg, rgba(16, 18, 20, 0.97), rgba(7, 8, 11, 0.98));
  border: 1px solid rgba(169, 255, 63, 0.27);
  border-top: 4px solid var(--green);
  box-shadow: 0 35px 100px rgba(0, 0, 0, 0.7);
}

.end-kicker {
  color: var(--green);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.4em;
}

.end-card h2 {
  margin: 8px 0 12px;
  font-family: Impact, "Arial Black", sans-serif;
  font-size: clamp(50px, 8vw, 86px);
  font-weight: 400;
  line-height: 0.85;
  letter-spacing: 0.01em;
}

.end-card p {
  max-width: 440px;
  color: #bdbcb3;
  font-size: 12px;
  line-height: 1.55;
}

.end-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 25px 0;
  background: rgba(255, 255, 255, 0.1);
}

.end-stats div { padding: 13px; background: #101115; }
.end-stats span { display: block; color: var(--muted); font-size: 7px; letter-spacing: 0.2em; }
.end-stats strong { display: block; margin-top: 4px; color: var(--green); font-family: Impact, "Arial Black", sans-serif; font-size: 26px; font-weight: 400; }

.end-card .primary-btn { width: 100%; }

.rotate-hint {
  position: absolute;
  z-index: 60;
  left: 50%;
  bottom: calc(132px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: rgba(6, 7, 11, 0.88);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: rgba(255, 255, 255, 0.64);
  font-size: 8px;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

.rotate-hint span { color: var(--yellow); font-size: 15px; }
.rotate-hint p { margin: 0; }

/* ------------------------------------------------------------------ */
/* Touch                                                               */
/* ------------------------------------------------------------------ */

.touch-ui { position: absolute; inset: 0; z-index: 20; pointer-events: none; }

.joystick {
  pointer-events: auto;
  position: absolute;
  left: max(22px, env(safe-area-inset-left, 0px));
  bottom: calc(23px + var(--safe-bottom));
  width: 126px;
  height: 126px;
  border: 1px solid rgba(255, 255, 255, 0.19);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.05), rgba(5, 6, 10, 0.4));
  touch-action: none;
}

.joystick::before,
.joystick::after {
  content: "";
  position: absolute;
  background: rgba(255, 255, 255, 0.1);
}
.joystick::before { left: 50%; top: 14%; bottom: 14%; width: 1px; }
.joystick::after { top: 50%; left: 14%; right: 14%; height: 1px; }

.stick {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 52px;
  height: 52px;
  margin: -26px 0 0 -26px;
  border: 1px solid rgba(255, 255, 255, 0.35);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.13);
  box-shadow: 0 0 18px rgba(0, 0, 0, 0.4);
}

.touch-actions {
  pointer-events: none;
  position: absolute;
  right: max(18px, env(safe-area-inset-right, 0px));
  bottom: calc(22px + var(--safe-bottom));
  width: 172px;
  height: 172px;
}

.touch-btn {
  pointer-events: auto;
  position: absolute;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background: rgba(8, 9, 14, 0.68);
  color: rgba(255, 255, 255, 0.8);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.09em;
  touch-action: none;
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.45);
}

.touch-btn:active { background: rgba(255, 255, 255, 0.2); transform: scale(0.96); }

.touch-btn.fire {
  right: 0;
  bottom: 34px;
  width: 79px;
  height: 79px;
  border-color: rgba(255, 83, 73, 0.6);
  color: #ffb1ac;
  font-size: 10px;
  background: rgba(57, 13, 17, 0.66);
}

.touch-btn.action {
  right: 90px;
  bottom: 0;
  width: 66px;
  height: 66px;
  border-color: rgba(169, 255, 63, 0.55);
  color: var(--green);
}

.touch-btn.sprint {
  right: 92px;
  bottom: 76px;
  width: 58px;
  height: 58px;
}

.touch-btn.small {
  right: 18px;
  bottom: 121px;
  width: 48px;
  height: 48px;
  font-size: 6px;
}

.touch-pause {
  pointer-events: auto;
  position: absolute;
  right: max(22px, env(safe-area-inset-right, 0px));
  top: calc(18px + var(--safe-top));
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 50%;
  background: rgba(7, 8, 12, 0.66);
  color: rgba(255, 255, 255, 0.72);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.04em;
}

/* ------------------------------------------------------------------ */
/* Responsive                                                          */
/* ------------------------------------------------------------------ */

@media (max-width: 900px) {
  .hud-top-left { left: 16px; top: calc(14px + var(--safe-top)); width: 205px; }
  .identity { margin-bottom: 6px; }
  .identity-mark { width: 29px; height: 29px; font-size: 17px; }
  .identity strong { font-size: 10px; }
  .identity span { font-size: 6px; }
  .bar { height: 9px; }
  .cash-row strong { font-size: 19px; }
  .hud-top-right { right: 16px; top: calc(14px + var(--safe-top)); }
  .wanted { font-size: 18px; }
  #clock { font-size: 14px; }
  .clock-row { font-size: 8px; }
  .icon-btn { display: none; }
  .mission-panel { left: 16px; top: calc(121px + var(--safe-top)); width: 238px; padding: 10px 12px 10px 14px; }
  .mission-panel h2 { font-size: 17px; }
  .mission-panel p { font-size: 9px; max-width: 206px; }
  .radar-wrap { width: 122px; height: 122px; left: auto; right: 16px; bottom: auto; top: calc(98px + var(--safe-top)); }
  .weapon-hud { right: 16px; bottom: calc(228px + var(--safe-bottom)); padding: 6px 8px; }
  .weapon-icon { width: 28px; height: 28px; font-size: 14px; }
  .weapon-hud strong { font-size: 8px; }
  .vehicle-hud { right: 16px; bottom: calc(270px + var(--safe-bottom)); }
  .prompt { bottom: calc(212px + var(--safe-bottom)); font-size: 8px; }
  .hint-bar { display: none; }
  .toast-stack { top: calc(14px + var(--safe-top)); width: 46vw; }
  .toast { font-size: 7px; padding: 6px 9px; }
  .mission-banner { top: 28%; }
  .mission-banner strong { font-size: 40px; }
  .objective-arrow { top: 76px; }
  .title-screen { padding: 20px 24px; }
  .title-core { padding-top: 0; }
  .logo-main { font-size: clamp(48px, 13vw, 104px); white-space: normal; }
  .logo-small { font-size: 8px; letter-spacing: 0.38em; }
  .logo-two { right: 0; bottom: -17px; width: 44px; height: 33px; font-size: 25px; }
  .tagline { font-size: 10px; }
  .title-controls { display: none; }
  .title-actions { gap: 14px; }
  .primary-btn { min-width: 220px; padding: 13px 15px; font-size: 9px; }
  .title-bottom p { display: none; }
  .title-bottom { justify-content: space-between; }
  .build-tag { margin-left: 0; }
  .pause-card { padding: 26px 24px 22px; }
  .end-card { padding: 28px 25px; }
  .end-stats { margin: 18px 0; }
}

@media (max-width: 520px) {
  .logo-main { font-size: 15vw; }
  .logo-small { font-size: 7px; }
  .logo-two { width: 38px; height: 29px; font-size: 21px; bottom: -14px; }
  .title-actions { flex-direction: column; align-items: flex-start; gap: 9px; }
  .title-topline .live-dot { display: none; }
  .mission-panel { width: 200px; top: calc(116px + var(--safe-top)); }
  .mission-panel p { font-size: 8px; }
  .radar-wrap { width: 104px; height: 104px; top: calc(91px + var(--safe-top)); }
  .weapon-hud { bottom: calc(209px + var(--safe-bottom)); }
  .vehicle-hud { bottom: calc(252px + var(--safe-bottom)); transform: scale(0.86); transform-origin: right bottom; }
  .prompt { bottom: calc(198px + var(--safe-bottom)); }
  .joystick { width: 112px; height: 112px; }
  .stick { width: 46px; height: 46px; margin: -23px 0 0 -23px; }
  .touch-actions { width: 154px; height: 154px; }
  .touch-btn.fire { width: 70px; height: 70px; bottom: 31px; }
  .touch-btn.action { right: 79px; width: 59px; height: 59px; }
  .touch-btn.sprint { right: 81px; bottom: 68px; width: 53px; height: 53px; }
  .touch-btn.small { right: 12px; bottom: 109px; width: 43px; height: 43px; }
  .end-card h2 { font-size: 49px; }
}

@media (max-height: 570px) and (orientation: landscape) {
  .hud-top-left { top: 9px; left: 14px; }
  .mission-panel { top: 100px; }
  .radar-wrap { width: 106px; height: 106px; top: 78px; }
  .weapon-hud { bottom: 25px; }
  .vehicle-hud { bottom: 88px; }
  .title-core { margin-top: auto; margin-bottom: auto; }
  .logo-main { font-size: 12vh; }
  .title-controls { display: none; }
  .title-bottom { display: none; }
  .title-topline { display: none; }
  .joystick { width: 100px; height: 100px; bottom: 12px; }
  .touch-actions { width: 150px; height: 150px; bottom: 10px; }
  .touch-btn.fire { width: 64px; height: 64px; bottom: 26px; }
  .touch-btn.action { right: 75px; width: 56px; height: 56px; }
  .touch-btn.sprint { right: 77px; bottom: 61px; width: 50px; height: 50px; }
  .touch-btn.small { right: 10px; bottom: 98px; width: 40px; height: 40px; }
  .prompt { bottom: 14px; }
  .toast-stack { top: 8px; }
}

body.touch #game { cursor: default; }
body.touch .hint-bar { display: none; }
body.touch .radar-wrap { top: calc(97px + var(--safe-top)); right: 16px; left: auto; bottom: auto; }
