@media (max-height: 570px) and (orientation: landscape) {
  body.touch .radar-wrap { top: 78px; }
  body.touch .weapon-hud { top: 194px; bottom: auto; }
  body.touch .vehicle-hud { top: 194px; left: 14px; right: auto; bottom: auto; transform: scale(.82); transform-origin: left top; }
  body.touch .prompt { bottom: 86px; }
}
```
